+    }
+
+    fn close(mut self) -> Result<()> {
+        fs::remove_dir_all(&self.path)?;
+        self.path.clear();
+        Ok(())
+    }
+
+    fn retain_for_ambiguity(mut self) {
+        self.path.clear();
