+        let mut incremental = edit.clone();
+        incremental.before = Some(prior_edit.content_hash.clone());
+        application.push(incremental);
+    }
+    if application.is_empty() {
+        bail!("Prepared repair contains no incremental file changes");
+    }
+    Ok(application)
