+        provider_id: packet.provider_id.clone(),
+        model_id: packet.model_id.clone(),
+        reasoning_effort: packet.reasoning_effort.clone(),
+        candidate_manifest: candidate_manifest.to_vec(),
+        files,
+        assets,
+    }
