+    pub schema_version: u16,
+    pub review_packet_sha256: String,
+    pub provider_id: String,
+    pub model_id: String,
+    pub reasoning_effort: String,
+    pub decision: DeveloperReviewDecisionKind,
+    pub blocking_findings: Vec<DeveloperReviewFinding>,
+    pub non_blocking_findings: Vec<DeveloperReviewFinding>,
+    pub validation_evidence_sha256: String,
+    pub reviewed_manifest_sha256: String,
+    pub reviewed_entry_count: u32,
+    pub ordered_batch_receipt_sha256s: Vec<String>,
+}
+
+impl DeveloperReviewAggregateOutput {
+    pub fn sha256(&self) -> Result<String> {
+        Ok(hex_digest(&serde_json::to_vec(self)?))
+    }
+
+    fn validate_exact(
+        &self,
+        set: &DeveloperReviewBatchSet,
+        receipts: &[DeveloperReviewBatchOutput],
+    ) -> Result<()> {
+        self.validate_exact_category(set, receipts)
+            .map_err(Into::into)
+    }
+
+    fn validate_exact_category(
+        &self,
+        set: &DeveloperReviewBatchSet,
+        receipts: &[DeveloperReviewBatchOutput],
+    ) -> std::result::Result<(), AggregateReviewValidationError> {
+        if receipts.len() != set.batches.len() {
+            return Err(AggregateReviewValidationError::ReceiptCount);
+        }
+        if receipts
+            .iter()
+            .enumerate()
+            .any(|(index, receipt)| receipt.batch_index as usize != index)
+        {
+            return Err(AggregateReviewValidationError::ReceiptOrder);
+        }
+        let receipt_hashes = receipts
+            .iter()
+            .map(DeveloperReviewBatchOutput::sha256)
+            .collect::<Result<Vec<_>>>()
+            .map_err(|_| AggregateReviewValidationError::ReceiptDigests)?;
+        if self.schema_version != 2 {
+            return Err(AggregateReviewValidationError::SchemaVersion);
+        }
+        if self.review_packet_sha256 != set.aggregate_candidate_sha256 {
+            return Err(AggregateReviewValidationError::CandidateDigest);
+        }
+        if self.provider_id != set.packet.provider_id {
+            return Err(AggregateReviewValidationError::Provider);
+        }
+        if self.model_id != set.packet.model_id {
+            return Err(AggregateReviewValidationError::Model);
+        }
+        if self.reasoning_effort != set.packet.reasoning_effort {
+            return Err(AggregateReviewValidationError::ReasoningEffort);
+        }
+        if self.validation_evidence_sha256 != set.packet.validation_evidence_sha256 {
+            return Err(AggregateReviewValidationError::ValidationEvidence);
+        }
+        if set
+            .manifest_sha256()
+            .map_or(true, |digest| self.reviewed_manifest_sha256 != digest)
+        {
+            return Err(AggregateReviewValidationError::ManifestDigest);
+        }
+        if u32::try_from(set.candidate_manifest.len())
+            .map_or(true, |count| self.reviewed_entry_count != count)
+        {
+            return Err(AggregateReviewValidationError::ReviewedEntryCount);
+        }
+        if self.ordered_batch_receipt_sha256s != receipt_hashes {
+            return Err(AggregateReviewValidationError::ReceiptDigests);
+        }
+        validate_review_findings_category(
+            &self.decision,
+            &self.blocking_findings,
+            &self.non_blocking_findings,
+            &set.candidate_manifest
+                .iter()
+                .map(DeveloperReviewedEntry::path)
+                .collect::<BTreeSet<_>>(),
+        )
+        .map_err(AggregateReviewValidationError::Findings)?;
+        let any_rejected = receipts
+            .iter()
+            .any(|receipt| receipt.decision == DeveloperReviewDecisionKind::Rejected);
+        if any_rejected && self.decision != DeveloperReviewDecisionKind::Rejected {
+            return Err(AggregateReviewValidationError::RejectedBatchOverwritten);
+        }
+        if receipts.iter().any(|receipt| {
+            receipt.blocking_findings.iter().any(|batch_finding| {
+                !self.blocking_findings.iter().any(|aggregate_finding| {
+                    aggregate_finding.path == batch_finding.path
+                        && aggregate_finding.message == batch_finding.message
+                })
+            })
+        }) {
+            return Err(AggregateReviewValidationError::BatchBlockerOmitted);
+        }
+        Ok(())
+    }
+}
+
+#[derive(Debug, thiserror::Error, PartialEq, Eq)]
+enum AggregateReviewValidationError {
+    #[error("Codex aggregate decision schema version mismatch")]
+    SchemaVersion,
+    #[error("Codex aggregate decision candidate digest mismatch")]
+    CandidateDigest,
+    #[error("Codex aggregate decision provider mismatch")]
+    Provider,
+    #[error("Codex aggregate decision model mismatch")]
+    Model,
+    #[error("Codex aggregate decision reasoning effort mismatch")]
+    ReasoningEffort,
+    #[error("Codex aggregate decision validation evidence mismatch")]
+    ValidationEvidence,
+    #[error("Codex aggregate decision manifest digest mismatch")]
+    ManifestDigest,
+    #[error("Codex aggregate decision reviewed entry count mismatch")]
+    ReviewedEntryCount,
+    #[error("Codex aggregate decision receipt digest mapping mismatch")]
+    ReceiptDigests,
+    #[error("Codex aggregate decision receipt count mismatch")]
+    ReceiptCount,
+    #[error("Codex aggregate decision receipt order mismatch")]
+    ReceiptOrder,
+    #[error(transparent)]
+    Findings(ReviewFindingsValidationError),
+    #[error("Codex aggregate decision overwrote a rejected batch")]
+    RejectedBatchOverwritten,
+    #[error("Codex aggregate decision omitted a batch blocker")]
+    BatchBlockerOmitted,
+}
+
+#[derive(Debug, thiserror::Error, PartialEq, Eq)]
+enum ReviewFindingsValidationError {
+    #[error("Codex decision contains too many findings")]
+    TooManyFindings,
+    #[error("Codex decision finding identifier format is invalid")]
+    FindingIdFormat,
+    #[error("Codex decision finding identifier is duplicated")]
+    DuplicateFindingId,
+    #[error("Codex decision finding path is outside reviewed scope")]
+    FindingPathScope,
+    #[error("Codex decision finding message is empty")]
+    FindingMessageEmpty,
+    #[error("Codex decision finding message exceeds the size limit")]
+    FindingMessageSize,
+    #[error("Codex decision finding message contains restricted data")]
+    FindingMessageRestrictedData,
+    #[error("Codex decision contradicts its blocking findings")]
+    ContradictoryDecision,
+}
+
+fn validate_review_findings_category(
+    decision: &DeveloperReviewDecisionKind,
+    blocking: &[DeveloperReviewFinding],
+    non_blocking: &[DeveloperReviewFinding],
+    paths: &BTreeSet<&str>,
+) -> std::result::Result<(), ReviewFindingsValidationError> {
+    if blocking.len() > MAX_FINDINGS || non_blocking.len() > MAX_FINDINGS {
+        return Err(ReviewFindingsValidationError::TooManyFindings);
+    }
+    let mut ids = BTreeSet::new();
+    for finding in blocking.iter().chain(non_blocking) {
+        if finding.finding_id.is_empty()
+            || finding.finding_id.len() > 128
+            || !finding
+                .finding_id
+                .as_bytes()
+                .first()
+                .is_some_and(u8::is_ascii_alphanumeric)
+            || !finding
+                .finding_id
+                .bytes()
+                .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
+        {
+            return Err(ReviewFindingsValidationError::FindingIdFormat);
+        }
+        if !ids.insert(finding.finding_id.as_str()) {
+            return Err(ReviewFindingsValidationError::DuplicateFindingId);
+        }
+        if !paths.contains(finding.path.as_str()) {
+            return Err(ReviewFindingsValidationError::FindingPathScope);
+        }
+        if finding.message.trim().is_empty() {
+            return Err(ReviewFindingsValidationError::FindingMessageEmpty);
+        }
+        if finding.message.len() > 1000 {
+            return Err(ReviewFindingsValidationError::FindingMessageSize);
+        }
+        if contains_secret_shape(&finding.message) {
+            return Err(ReviewFindingsValidationError::FindingMessageRestrictedData);
+        }
+    }
+    match decision {
+        DeveloperReviewDecisionKind::Approved if !blocking.is_empty() => {
+            Err(ReviewFindingsValidationError::ContradictoryDecision)
+        }
+        DeveloperReviewDecisionKind::Rejected if blocking.is_empty() => {
+            Err(ReviewFindingsValidationError::ContradictoryDecision)
+        }
+        _ => Ok(()),
+    }
+}
