+fn output_schema_const(value: serde_json::Value) -> Result<serde_json::Value> {
+    let value_type = match &value {
+        serde_json::Value::Bool(_) => "boolean",
+        serde_json::Value::Number(number) if number.is_i64() || number.is_u64() => "integer",
+        serde_json::Value::Number(_) => "number",
+        serde_json::Value::String(_) => "string",
+        _ => bail!("Output schema constant must be a provider-supported primitive"),
+    };
+    Ok(serde_json::json!({"type": value_type, "const": value}))
+}
+
+fn bind_output_schema_const(
+    schema: &mut serde_json::Value,
+    property: &str,
+    value: serde_json::Value,
+) -> Result<()> {
+    let slot = schema
+        .get_mut("properties")
+        .and_then(serde_json::Value::as_object_mut)
+        .and_then(|properties| properties.get_mut(property))
+        .with_context(|| format!("Output schema is missing the {property} property"))?;
+    *slot = output_schema_const(value)?;
+    Ok(())
+}
+
+fn bind_finding_path_domain(schema: &mut serde_json::Value, paths: Vec<&str>) -> Result<()> {
+    if paths.is_empty() {
+        bail!("Output schema finding path domain is empty");
+    }
+    let slot = schema
+        .get_mut("$defs")
+        .and_then(serde_json::Value::as_object_mut)
+        .and_then(|definitions| definitions.get_mut("finding"))
+        .and_then(|finding| finding.get_mut("properties"))
+        .and_then(serde_json::Value::as_object_mut)
+        .and_then(|properties| properties.get_mut("path"))
+        .context("Output schema is missing the finding path property")?;
+    *slot = serde_json::json!({"type": "string", "enum": paths});
+    Ok(())
+}
+
+fn reviewed_entry_output_schema(entry: &DeveloperReviewedEntry) -> Result<serde_json::Value> {
+    let (properties, required) = match entry {
+        DeveloperReviewedEntry::File(file) => (
+            serde_json::json!({
+                "kind": output_schema_const(serde_json::json!("file"))?,
+                "path": output_schema_const(serde_json::json!(file.path))?,
+                "content_sha256": output_schema_const(serde_json::json!(file.content_sha256))?,
+                "classification": output_schema_const(serde_json::json!(file.classification))?,
+            }),
+            serde_json::json!(["kind", "path", "content_sha256", "classification"]),
+        ),
+        DeveloperReviewedEntry::Asset(asset) => (
+            serde_json::json!({
+                "kind": output_schema_const(serde_json::json!("asset"))?,
+                "path": output_schema_const(serde_json::json!(asset.path))?,
+                "content_sha256": output_schema_const(serde_json::json!(asset.content_sha256))?,
+                "media_type": output_schema_const(serde_json::json!(asset.media_type))?,
+                "width": output_schema_const(serde_json::json!(asset.width))?,
+                "height": output_schema_const(serde_json::json!(asset.height))?,
+                "classification": output_schema_const(serde_json::json!(asset.classification))?,
+            }),
+            serde_json::json!([
+                "kind",
+                "path",
+                "content_sha256",
+                "media_type",
+                "width",
+                "height",
+                "classification"
+            ]),
+        ),
+    };
+    Ok(serde_json::json!({
+        "type": "object",
+        "additionalProperties": false,
+        "properties": properties,
+        "required": required,
+    }))
+}
