+fn batch_output_schema(batch: &DeveloperReviewBatch) -> Result<String> {
+    batch.validate()?;
+    let mut schema: serde_json::Value = serde_json::from_str(BATCH_OUTPUT_SCHEMA)?;
+    let reviewed_entries = reviewed_entries_for_batch(batch);
+    let reviewed_entry_branches = reviewed_entries
+        .iter()
+        .map(reviewed_entry_output_schema)
+        .collect::<Result<Vec<_>>>()?;
+    bind_finding_path_domain(
+        &mut schema,
+        reviewed_entries
+            .iter()
+            .map(DeveloperReviewedEntry::path)
+            .collect(),
+    )?;
+    for (property, value) in [
+        ("schema_version", serde_json::json!(2)),
+        ("review_batch_sha256", serde_json::json!(batch.sha256()?)),
+        (
+            "aggregate_candidate_sha256",
+            serde_json::json!(batch.aggregate_candidate_sha256),
+        ),
+        ("batch_index", serde_json::json!(batch.batch_index)),
+        ("batch_count", serde_json::json!(batch.batch_count)),
+        ("provider_id", serde_json::json!(batch.provider_id)),
+        ("model_id", serde_json::json!(batch.model_id)),
+        (
+            "reasoning_effort",
+            serde_json::json!(batch.reasoning_effort),
+        ),
+        (
+            "validation_evidence_sha256",
+            serde_json::json!(batch.validation_evidence_sha256),
+        ),
+    ] {
+        bind_output_schema_const(&mut schema, property, value)?;
+    }
+    let reviewed_entries_schema = schema
+        .get_mut("properties")
+        .and_then(serde_json::Value::as_object_mut)
+        .and_then(|properties| properties.get_mut("reviewed_entries"))
+        .context("Output schema is missing the reviewed_entries property")?;
+    *reviewed_entries_schema = serde_json::json!({
+        "type": "array",
+        "minItems": reviewed_entries.len(),
+        "maxItems": reviewed_entries.len(),
+        "items": {"anyOf": reviewed_entry_branches},
+    });
+    Ok(serde_json::to_string(&schema)?)
+}
+
+fn aggregate_output_schema(
+    set: &DeveloperReviewBatchSet,
+    receipt_hashes: &[String],
+) -> Result<String> {
+    set.validate()?;
+    if receipt_hashes.len() != set.batches.len()
+        || receipt_hashes.iter().any(|hash| !valid_digest(hash))
+    {
+        bail!("Aggregate output schema receipt binding is invalid");
+    }
+    let mut schema: serde_json::Value = serde_json::from_str(AGGREGATE_OUTPUT_SCHEMA)?;
+    bind_finding_path_domain(
+        &mut schema,
+        set.candidate_manifest
+            .iter()
+            .map(DeveloperReviewedEntry::path)
+            .collect(),
+    )?;
+    for (property, value) in [
+        ("schema_version", serde_json::json!(2)),
+        (
+            "review_packet_sha256",
+            serde_json::json!(set.aggregate_candidate_sha256),
+        ),
+        ("provider_id", serde_json::json!(set.packet.provider_id)),
+        ("model_id", serde_json::json!(set.packet.model_id)),
+        (
+            "reasoning_effort",
+            serde_json::json!(set.packet.reasoning_effort),
+        ),
+        (
+            "validation_evidence_sha256",
+            serde_json::json!(set.packet.validation_evidence_sha256),
+        ),
+        (
+            "reviewed_manifest_sha256",
+            serde_json::json!(set.manifest_sha256()?),
+        ),
+        (
+            "reviewed_entry_count",
+            serde_json::json!(set.candidate_manifest.len()),
+        ),
+    ] {
+        bind_output_schema_const(&mut schema, property, value)?;
+    }
+    let receipt_schema = schema
+        .get_mut("properties")
+        .and_then(serde_json::Value::as_object_mut)
+        .and_then(|properties| properties.get_mut("ordered_batch_receipt_sha256s"))
+        .context("Output schema is missing the ordered_batch_receipt_sha256s property")?;
+    *receipt_schema = serde_json::json!({
+        "type": "array",
+        "minItems": receipt_hashes.len(),
+        "maxItems": receipt_hashes.len(),
+        "items": {"type": "string", "enum": receipt_hashes},
+    });
+    Ok(serde_json::to_string(&schema)?)
+}
