+            (
+                AggregateReviewValidationError::Provider,
+                Box::new(|value| value.provider_id = "other.provider".into()),
+            ),
+            (
+                AggregateReviewValidationError::Model,
+                Box::new(|value| value.model_id = "other-model".into()),
+            ),
+            (
+                AggregateReviewValidationError::ReasoningEffort,
+                Box::new(|value| value.reasoning_effort = "medium".into()),
+            ),
+            (
+                AggregateReviewValidationError::ValidationEvidence,
+                Box::new(|value| {
+                    value.validation_evidence_sha256 = hex_digest(b"other validation")
+                }),
+            ),
+            (
+                AggregateReviewValidationError::ManifestDigest,
+                Box::new(|value| value.reviewed_manifest_sha256 = hex_digest(b"other manifest")),
+            ),
+            (
+                AggregateReviewValidationError::ReviewedEntryCount,
+                Box::new(|value| value.reviewed_entry_count += 1),
+            ),
+            (
+                AggregateReviewValidationError::ReceiptDigests,
+                Box::new(|value| {
+                    value.ordered_batch_receipt_sha256s[0] = hex_digest(b"other receipt")
+                }),
+            ),
+            (
+                AggregateReviewValidationError::ReceiptDigests,
+                Box::new(|value| value.ordered_batch_receipt_sha256s.reverse()),
+            ),
+            (
+                AggregateReviewValidationError::ReceiptDigests,
+                Box::new(|value| {
+                    value
+                        .ordered_batch_receipt_sha256s
+                        .pop()
+                        .map(|_| ())
+                        .unwrap()
+                }),
+            ),
+            (
+                AggregateReviewValidationError::ReceiptDigests,
+                Box::new(|value| {
+                    value.ordered_batch_receipt_sha256s[1] =
+                        value.ordered_batch_receipt_sha256s[0].clone()
+                }),
+            ),
+        ];
