+        rejected_receipts[0].blocking_findings.push(blocker.clone());
+        let overwritten = aggregate_output(&set, &rejected_receipts);
+        assert_eq!(
+            overwritten.validate_exact_category(&set, &rejected_receipts),
+            Err(AggregateReviewValidationError::RejectedBatchOverwritten)
+        );
+        let mut omitted = aggregate_output(&set, &rejected_receipts);
+        omitted.decision = DeveloperReviewDecisionKind::Rejected;
+        omitted.blocking_findings.push(DeveloperReviewFinding {
+            finding_id: "different-blocker".into(),
+            path: set.candidate_manifest[1].path().into(),
+            message: "A different aggregate defect remains blocking.".into(),
