+        assert_eq!(
+            omitted.validate_exact_category(&set, &rejected_receipts),
+            Err(AggregateReviewValidationError::BatchBlockerOmitted)
+        );
+        omitted.blocking_findings.push(blocker);
+        omitted
+            .validate_exact_category(&set, &rejected_receipts)
+            .unwrap();
+    }
