@@ -0,0 +1,41 @@
+use assemblywright_protocol::windows_execution_pipe::{
+    serve_once, transact, WindowsExecutionPipeError,
+};
+
+pub fn serve_active_broker_once(
+    pipe_name: &str,
+    executor_service_sid: &str,
+    expected_broker_service_sid: &str,
+    handler: impl FnOnce(&[u8]) -> Result<Vec<u8>, WindowsExecutionPipeError>,
+) -> Result<(), WindowsExecutionPipeError> {
+    serve_once(
+        pipe_name,
+        executor_service_sid,
+        expected_broker_service_sid,
+        handler,
+    )
+}
+
+pub fn serve_urgent_broker_once(
+    pipe_name: &str,
+    executor_service_sid: &str,
+    expected_broker_service_sid: &str,
+    handler: impl FnOnce(&[u8]) -> Result<Vec<u8>, WindowsExecutionPipeError>,
+) -> Result<(), WindowsExecutionPipeError> {
+    serve_once(
+        pipe_name,
+        executor_service_sid,
+        expected_broker_service_sid,
+        handler,
+    )
+}
+
+pub fn wake_active_pipe(
+    pipe_name: &str,
+    expected_executor_service_sid: &str,
+) -> Result<(), WindowsExecutionPipeError> {
+    // The server rejects this Executor-token client because the active endpoint
+    // admits only the Broker SID. The rejected connection exists solely to
+    // release a blocking ConnectNamedPipe during SCM cancellation.
+    transact(pipe_name, expected_executor_service_sid, b"shutdown-wakeup").map(|_| ())
+}

diff --git a/crates/assemblywright-master/tests/assembly_line_execution_status_http.rs b/crates/assemblywright-master/tests/assembly_line_execution_status_http.rs
new file mode 100644
index 0000000000000000000000000000000000000000..35daba405cdb27d663e840cddf1a3d027a031623
--- /dev/null
+++ b/crates/assemblywright-master/tests/assembly_line_execution_status_http.rs
@@ -0,0 +1,120 @@
+use assemblywright_protocol::{AssemblyLineExecutionStatusProjection, AssemblyLineOwnerProjection};
+use serde_json::Value;
+use std::io::{BufRead, BufReader, Read, Write};
+use std::net::{SocketAddr, TcpListener, TcpStream};
+use std::path::Path;
+use std::process::{Child, Command, Stdio};
+
+struct ChildGuard(Child);
+
+impl Drop for ChildGuard {
+    fn drop(&mut self) {
+        let _ = self.0.kill();
+        let _ = self.0.wait();
+    }
+}
+
+#[test]
+fn execution_status_is_authenticated_read_only_and_never_fabricates_start_admission() {
+    let directory = tempfile::tempdir().unwrap();
+    let binary = env!("CARGO_BIN_EXE_assemblywright-master");
+    assert!(Command::new(binary)
+        .arg("--data-dir")
+        .arg(directory.path())
+        .arg("setup")
+        .status()
+        .unwrap()
+        .success());
+    let endpoint = unused_loopback_addr();
+    let mut server = spawn_server(binary, directory.path(), endpoint);
+    read_ready(&mut server.0);
+    let token = std::fs::read_to_string(directory.path().join("development.token")).unwrap();
+    let token = token.trim();
+
+    let unauthorized = get_request(endpoint, "/v1/assembly-line/execution-status", None);
+    assert!(
+        unauthorized.starts_with("HTTP/1.1 401 Unauthorized"),
+        "{unauthorized}"
+    );
+
+    let before: AssemblyLineOwnerProjection =
+        response_json(&get_request(endpoint, "/v1/assembly-line", Some(token)));
+    let response = get_request(endpoint, "/v1/assembly-line/execution-status", Some(token));
+    assert!(response.starts_with("HTTP/1.1 200 OK"), "{response}");
+    let status: AssemblyLineExecutionStatusProjection = response_json(&response);
+    assert!(status.start_binding.is_none());
+    assert_eq!(status.owner.assembly_line, before.assembly_line);
+    assert_eq!(status.owner.queue, before.queue);
+    assert_eq!(status.owner.repositories, before.repositories);
+    assert_eq!(
+        status.owner.owner_control_revision,
+        before.owner_control_revision
+    );
+    assert_eq!(
+        status.owner.emergency_pause_revision,
+        before.emergency_pause_revision
+    );
+
+    let after: AssemblyLineOwnerProjection =
+        response_json(&get_request(endpoint, "/v1/assembly-line", Some(token)));
+    assert_eq!(after.assembly_line, before.assembly_line);
+    assert_eq!(after.queue, before.queue);
+    assert_eq!(after.repositories, before.repositories);
+    assert_eq!(after.owner_control_revision, before.owner_control_revision);
+    assert_eq!(
+        after.emergency_pause_revision,
+        before.emergency_pause_revision
+    );
+}
+
+fn spawn_server(binary: &str, data_dir: &Path, endpoint: SocketAddr) -> ChildGuard {
+    ChildGuard(
+        Command::new(binary)
+            .arg("--data-dir")
+            .arg(data_dir)
+            .arg("serve")
+            .arg("--bind")
+            .arg(endpoint.to_string())
+            .stdout(Stdio::piped())
+            .stderr(Stdio::piped())
+            .spawn()
+            .unwrap(),
+    )
+}
+
+fn read_ready(child: &mut Child) {
+    let mut line = String::new();
+    BufReader::new(child.stdout.take().unwrap())
+        .read_line(&mut line)
+        .unwrap();
+    assert_eq!(
+        serde_json::from_str::<Value>(&line).unwrap()["status"],
+        "ready"
+    );
+}
+
+fn unused_loopback_addr() -> SocketAddr {
+    TcpListener::bind("127.0.0.1:0")
+        .unwrap()
+        .local_addr()
+        .unwrap()
+}
+
+fn get_request(endpoint: SocketAddr, path: &str, token: Option<&str>) -> String {
+    let mut stream = TcpStream::connect(endpoint).unwrap();
+    let authorization = token
+        .map(|token| format!("Authorization: Bearer {token}\r\n"))
+        .unwrap_or_default();
+    write!(
+        stream,
+        "GET {path} HTTP/1.1\r\nHost: {endpoint}\r\n{authorization}Content-Length: 0\r\nConnection: close\r\n\r\n"
+    )
+    .unwrap();
+    let mut response = String::new();
+    stream.read_to_string(&mut response).unwrap();
+    response
+}
+
+fn response_json<T: serde::de::DeserializeOwned>(response: &str) -> T {
+    serde_json::from_str(response.split_once("\r\n\r\n").unwrap().1).unwrap()
+}

