+#![cfg(windows)]
+
+use assemblywright_master::{
+    current_time_ms, EnrollmentGrantSpec, EnrollmentRequest, IdentityAuthority, MasterProcess,
+    PlatformSecretProtector,
+};
+use assemblywright_protocol::{
+    AssemblyLineExecutionStatusProjection, AuthenticatedHandshakeRequest, CapabilityDescriptor,
+    DeviceRole, HandshakeRequest, HandshakeResponse, PROTOCOL_VERSION,
+};
+use rcgen::{CertificateParams, DistinguishedName, DnType, IsCa, KeyPair};
+use rustls::pki_types::{CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer, ServerName};
+use rustls::{ClientConfig, RootCertStore};
+use serde::Serialize;
+use serde_json::Value;
+use sha2::{Digest, Sha256};
+use std::io::{BufRead, BufReader};
+use std::net::{SocketAddr, TcpListener};
+use std::path::Path;
+use std::process::{Child, Command, Stdio};
+use std::sync::Arc;
+use tokio::io::{AsyncReadExt, AsyncWriteExt};
+use tokio_rustls::TlsConnector;
+
+const TLS_EXPORTER_LABEL: &[u8] = b"EXPORTER-Assemblywright-Developer-Mode-v1";
+
+struct ChildGuard(Child);
+
+impl Drop for ChildGuard {
+    fn drop(&mut self) {
+        let _ = self.0.kill();
+        let _ = self.0.wait();
+    }
+}
+
+struct EnrolledClient {
+    config: Arc<ClientConfig>,
+    handshake: HandshakeRequest,
+}
+
+#[tokio::test(flavor = "multi_thread")]
+async fn execution_status_requires_current_designated_mac_mtls_and_is_read_only() {
+    let _ = rustls::crypto::ring::default_provider().install_default();
+    let directory = tempfile::tempdir().unwrap();
+    let binary = env!("CARGO_BIN_EXE_assemblywright-master");
+    let setup = Command::new(binary)
+        .arg("--data-dir")
+        .arg(directory.path())
+        .arg("setup")
+        .output()
+        .unwrap();
+    assert!(
+        setup.status.success(),
+        "{}",
+        String::from_utf8_lossy(&setup.stderr)
+    );
+    let designated = enroll_client(
+        directory.path(),
+        "designated-execution-status-mac",
+        DeviceRole::MacBridge,
+        vec![CapabilityDescriptor::mlx_reasoning(
+            "owner-execution-status",
+            32 * 1024,
+            32 * 1024,
+        )],
+    );
+    let stale_designation = enroll_client(
+        directory.path(),
+        "previous-execution-status-mac",
+        DeviceRole::MacBridge,
+        vec![CapabilityDescriptor::mlx_reasoning(
+            "owner-execution-status",
+            32 * 1024,
+            32 * 1024,
+        )],
+    );
+    let wrong_role = enroll_client(
+        directory.path(),
+        "execution-status-worker",
+        DeviceRole::InferenceWorker,
+        vec![CapabilityDescriptor::local_coding()],
+    );
+    {
+        let mut process = MasterProcess::acquire(directory.path()).unwrap();
+        process
+            .kernel_mut()
+            .designate_owner_control_bridge(designated.handshake.device_id, 0, 10)
+            .unwrap();
+    }
+    let local_endpoint = unused_loopback_addr();
+    let remote_endpoint = unused_loopback_addr();
+    let mut server = spawn_server(binary, directory.path(), local_endpoint, remote_endpoint);
+    read_ready(&mut server.0);
+
+    let pre_handshake = one_shot_request(
+        remote_endpoint,
+        designated.config.clone(),
+        "GET",
+        "/v1/distributed/assembly-line/execution-status",
+        &[],
+    )
+    .await;
+    assert!(
+        pre_handshake.starts_with("HTTP/1.1 401 Unauthorized"),
+        "{pre_handshake}"
+    );
+
+    for denied in [&stale_designation, &wrong_role] {
+        let response = authenticated_request(
+            remote_endpoint,
+            denied,
+            "GET",
+            "/v1/distributed/assembly-line/execution-status",
+            &serde_json::json!({}),
+        )
+        .await;
+        assert!(
+            response.starts_with("HTTP/1.1 401 Unauthorized"),
+            "{response}"
+        );
+    }
+
+    let first_response = authenticated_request(
+        remote_endpoint,
+        &designated,
+        "GET",
+        "/v1/distributed/assembly-line/execution-status",
+        &serde_json::json!({}),
+    )
+    .await;
+    assert!(
+        first_response.starts_with("HTTP/1.1 200 OK"),
+        "{first_response}"
+    );
+    let first: AssemblyLineExecutionStatusProjection = response_json(&first_response);
+    assert!(first.start_binding.is_none());
+
+    let second_response = authenticated_request(
+        remote_endpoint,
+        &designated,
+        "GET",
+        "/v1/distributed/assembly-line/execution-status",
+        &serde_json::json!({}),
+    )
+    .await;
+    assert!(
+        second_response.starts_with("HTTP/1.1 200 OK"),
+        "{second_response}"
+    );
+    let second: AssemblyLineExecutionStatusProjection = response_json(&second_response);
+    assert!(second.start_binding.is_none());
+    assert_eq!(second.owner.assembly_line, first.owner.assembly_line);
+    assert_eq!(second.owner.queue, first.owner.queue);
+    assert_eq!(second.owner.repositories, first.owner.repositories);
+    assert_eq!(
+        second.owner.owner_control_revision,
